#!/usr/bin/env node
import { readFileSync } from 'node:fs';

const commitMsgFile = process.argv[2];

if (!commitMsgFile) {
  console.error('Error: No commit message file path provided.');
  process.exit(1);
}

const rawMessage = readFileSync(commitMsgFile, 'utf8');
const message = rawMessage.trim();

// Ignore merge and revert commits generated by git
if (
  message.startsWith('Merge ') ||
  message.startsWith('Revert ') ||
  message.startsWith('fixup! ') ||
  message.startsWith('squash! ')
) {
  process.exit(0);
}

const firstLine = message.split('\n')[0].trim();

// Angular Conventional Commits regex with devai type
// Format: <type>(<scope>): <subject>
// or:     <type>: <subject>
const conventionalCommitRegex =
  /^(feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert|devai)(\([a-zA-Z0-9_\-./]+\))?!?: [^\n\r]+$/;

if (!conventionalCommitRegex.test(firstLine)) {
  console.error('\n\x1b[31m[INVALID COMMIT MESSAGE]\x1b[0m');
  console.error(`"${firstLine}"\n`);
  console.error('Commit messages must follow the Angular Conventional Commits convention:');
  console.error('  <type>(<optional-scope>): <description>\n');
  console.error('Allowed types:');
  console.error('  feat     - A new feature');
  console.error('  fix      - A bug fix');
  console.error('  docs     - Documentation changes');
  console.error('  style    - Code style/formatting without logic changes');
  console.error('  refactor - Code changes that neither fix bugs nor add features');
  console.error('  perf     - Performance improvements');
  console.error('  test     - Adding or updating tests');
  console.error('  build    - Build system or dependency changes');
  console.error('  ci       - CI configuration and scripts');
  console.error('  chore    - Maintenance and tooling tasks');
  console.error('  revert   - Reverting a previous commit');
  console.error('  devai    - AI agent instructions, prompts, skills, or tooling (AGENTS.md, .pi/)\n');
  console.error('Examples:');
  console.error('  feat(core): implement planet resource generation');
  console.error('  devai(skills): update autonomous work-on-issue workflow');
  console.error('  docs(architecture): add building blocks overview\n');
  process.exit(1);
}

if (firstLine.length > 100) {
  console.warn(
    `\x1b[33m[WARNING]\x1b[0m Commit header length (${firstLine.length}) exceeds recommended 72-100 characters.`
  );
}

process.exit(0);
